    SensorB : REAL := 46.0;
    MaxDeviation : REAL := 2.0;
    SensorMismatch : BOOL;
    PowerOK : BOOL := TRUE;
    SensorFault : BOOL;
    RawValue : REAL := 95.0;
    AutoMode : BOOL := TRUE;
    LoopCounter : INT := 0;
    DataArray : ARRAY [0..4] OF REAL := [10.0, 20.0, 30.0, 40.0, 50.0];
END_VAR
(* Validate OuterSetpoint *)
IF OuterSetpoint < 0.0 THEN
    OuterSetpoint := 0.0;
ELSIF OuterSetpoint > 200.0 THEN
    OuterSetpoint := 200.0;
END_IF;
